import {adaptationPosition} from './special-cell-models.js?v=20261023-physicscomplete01';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let serial=0;
export function specialCellFigure({type='sperm',adapted=true,step=0,labelled=false}={}){
 type=['sperm','nerve','muscle','root','xylem','phloem'].includes(type)?type:'sperm';const id='special'+(++serial),v=adaptationPosition(type,adapted,step),line='stroke="#e5edf0" stroke-width="3" fill="none"',coral='#f48b78';let art='';
 if(type==='sperm'){const x=58+v;art='<g transform="translate('+x+' 170)"><ellipse rx="27" ry="37" fill="url(#'+id+'gel)"/><ellipse rx="15" ry="25" fill="#bf8290"/><rect x="25" y="-11" width="38" height="22" rx="8" fill="#dfb784"/>'+Array.from({length:4},(_,i)=>'<ellipse cx="'+(31+i*8)+'" cy="0" rx="3" ry="7" fill="#917a69"/>').join('')+(adapted?'<path d="M63 0 Q95 '+(step%2?28:-28)+' 126 0 T190 0" '+line+'/>':'')+'</g>';}
 if(type==='nerve'){const end=adapted?355:175;art='<g stroke="#94b3bd" stroke-width="7" fill="none"><path d="M75 163 L35 85 M75 163 L22 175 M75 163 L37 242 M75 163 H'+end+'"/>'+[[35,85],[22,175],[37,242]].map(([x,y])=>'<path d="M'+x+' '+y+' l-15 -18 M'+x+' '+y+' l-17 10"/>').join('')+'<path d="M'+end+' 163 l25 -30 M'+end+' 163 l25 30"/></g><circle cx="75" cy="163" r="33" fill="url(#'+id+'gel)"/><circle cx="75" cy="163" r="13" fill="#bf8290"/>'+(adapted?'<path d="M140 163 H330" stroke="#dfb784" stroke-width="12" stroke-dasharray="25 9"/>':'')+'<circle cx="'+(97+v)+'" cy="163" r="7" fill="'+coral+'"/><text x="210" y="290" fill="#e5edf0" font-size="13" text-anchor="middle">Marker = electrical impulse</text>';}
 if(type==='muscle'){const width=300-v;art='<rect x="52" y="111" width="'+width+'" height="106" rx="50" fill="url(#'+id+'gel)"/>'+(adapted?[135,158,181].map(y=>'<path d="M65 '+y+' H'+(40+width)+'" stroke="#d6b5aa" stroke-width="13"/>').join('')+Array.from({length:14},(_,i)=>'<path d="M'+(74+i*(width-40)/14)+' 126 V196" stroke="#8b6b77" stroke-width="3"/>').join(''):'')+'<ellipse cx="80" cy="198" rx="15" ry="7" fill="#bf8290"/><path d="M'+(52+width)+' 105 V225" stroke="'+coral+'" stroke-width="3"/>';}
 if(type==='root'){const body='M55 66 H177 Q195 66 195 87 V121 '+(adapted?'H326 Q348 121 348 143 Q348 165 326 165 H195 ':'')+'V244 Q195 266 173 266 H77 Q55 266 55 244 Z';art='<path d="'+body+'" fill="url(#'+id+'gel)" stroke="#c3d4c7" stroke-width="6"/><ellipse cx="113" cy="198" rx="24" ry="30" fill="#bf8290"/><rect x="76" y="87" width="86" height="80" rx="20" fill="#abc6ce" opacity=".65"/><path d="'+body+'" fill="none" stroke="'+coral+'" stroke-width="3" pathLength="100" stroke-dasharray="8 92" stroke-dashoffset="'+(-step*16)+'"/><text x="210" y="312" fill="#e5edf0" font-size="13" text-anchor="middle">Trace the membrane boundary</text>';}
 if(type==='xylem'){art='<path d="M130 35 V295 M255 35 V295" stroke="#cfb18e" stroke-width="18"/>'+[88,171,254].map(y=>'<path d="M130 '+y+' h-13 M255 '+y+' h13" stroke="#dbe4d6" stroke-width="7"/>'+(!adapted?'<path d="M139 '+y+' H246" stroke="#c4d1ca" stroke-width="8"/>':'')).join('')+'<path d="M150 46 H235 V287 H150Z" fill="#9bbac4" opacity=".2"/><circle cx="192" cy="'+(281-v)+'" r="9" fill="'+coral+'"/><path d="M192 255 V57 l-9 15 m9 -15 l9 15" '+line+'/><text x="310" y="173" text-anchor="middle" fill="#e5edf0" font-size="12">Water</text>';}
 if(type==='phloem'){art='<rect x="42" y="112" width="328" height="106" rx="15" fill="url(#'+id+'gel)"/>'+[146,255].map(x=>'<path d="M'+x+' 113 V217" stroke="#d5e0d7" stroke-width="8"/>'+(adapted?[137,163,190].map(y=>'<circle cx="'+x+'" cy="'+y+'" r="5" fill="#4e7487"/>').join(''):'' )).join('')+'<rect x="168" y="54" width="84" height="48" rx="20" fill="#dfb784"/><circle cx="187" cy="78" r="10" fill="#b47d87"/><text x="210" y="40" fill="#e5edf0" text-anchor="middle" font-size="13">Companion cell</text><circle cx="'+(61+v)+'" cy="163" r="7" fill="'+coral+'"/><path d="M66 245 H343 l-12 -7 m12 7 l-12 7" '+line+'/><text x="210" y="284" text-anchor="middle" fill="#e5edf0" font-size="13">One source-to-sink path</text>';}
 const title=labelled?type+' adaptation model':'Specialised cell: schematic evidence';return '<svg class="bio-cell-art" viewBox="0 0 420 330" role="img" aria-label="'+safe(title)+'"><title>'+safe(title)+'</title><desc>Symbolic geometry and process markers. Counterfactual comparisons do not model real speeds, forces or transport mechanisms.</desc><defs><radialGradient id="'+id+'gel" cx="30%" cy="25%"><stop stop-color="#cbdcd8"/><stop offset="1" stop-color="#5c8398"/></radialGradient></defs>'+art+'</svg>';
}
export function fateFigure({context='animal',target='nerve',stage=0}={}){const n=Math.max(0,Math.min(2,Math.floor(Number(stage)||0)));if(n===2&&target!=='repair')return specialCellFigure({type:target,adapted:true,step:0});const adult=context==='adult',centres=adult?[100,180,260,340]:[210];return '<svg class="bio-cell-art" viewBox="0 0 420 330" role="img" aria-label="'+safe(adult?'Illustrative adult tissue repair, stage '+n:'Illustrative development, stage '+n)+'"><title>'+safe(adult?'Repair and replacement':'Cell development')+'</title><desc>Three model stages are not named cell-cycle phases or real developmental time. Branch selection represents possible outcomes, not conscious cell choice.</desc>'+centres.map((x,i)=>adult&&i===2&&n<2?'<rect x="'+(x-29)+'" y="137" width="58" height="74" fill="none" stroke="#f48b78" stroke-dasharray="4 5"/>':'<ellipse cx="'+x+'" cy="174" rx="'+(n===1?28:35)+'" ry="'+(n===1?46:35)+'" fill="#9db8bd" stroke="#d4dfe7" stroke-width="2"/><circle cx="'+x+'" cy="174" r="13" fill="#c48a92"/>').join('')+(n===1?'<text x="210" y="270" fill="#e5edf0" text-anchor="middle" font-size="15">'+(adult?'Cells divide to replace lost cells':'Specialised structures develop')+'</text>':'')+'</svg>';}
